//! Engine configuration: JSON generated by the NixOS module (never contains
//! secrets, only the path of the API key file), merged over defaults. Paths
//! may use `~` and `$XDG_*`, resolved per user since the engine is a
//! systemd user service.

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::PathBuf;

pub const DEFAULT_CONFIG_PATH: &str = "/etc/minisoc/engine.json";

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Config {
    pub spool_dirs: Vec<String>,
    pub inbox_dir: String,
    pub state_dir: String,
    pub runtime_dir: String,
    pub poll_interval_ms: u64,
    pub log_level: String,
    pub sources: BTreeMap<String, SourceCfg>,
    pub filter: FilterCfg,
    pub retention: RetentionCfg,
    pub ai: AiCfg,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            spool_dirs: vec!["/var/lib/minisoc-collector/spool".into()],
            inbox_dir: "$XDG_STATE_HOME/minisoc/inbox".into(),
            state_dir: "$XDG_STATE_HOME/minisoc".into(),
            runtime_dir: "$XDG_RUNTIME_DIR/minisoc".into(),
            poll_interval_ms: 1000,
            log_level: "info".into(),
            sources: BTreeMap::new(),
            filter: FilterCfg::default(),
            retention: RetentionCfg::default(),
            ai: AiCfg::default(),
        }
    }
}

/// Per-source normalization settings (parsing itself happens in Vector).
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct SourceCfg {
    /// "generic" (field mapping + heuristics) or "rustinel".
    pub normalizer: Option<String>,
    /// Field paths for timestamp / severity / event_type / message.
    pub mapping: BTreeMap<String, String>,
    /// Source severity value (lower-cased) -> MiniSOC severity.
    pub severity_map: BTreeMap<String, String>,
    pub default_severity: Option<String>,
    /// Static event type when the source has none.
    pub event_type: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct FilterCfg {
    /// Custom user rules file; wins over `default_file`.
    pub file: Option<String>,
    pub default_file: String,
    /// Read-only rule files managed by NixOS (evaluated first).
    pub system_files: Vec<String>,
    /// Rules owned by the AI (auto-filter, scheduled filter review). The AI
    /// never writes the user file.
    pub ai_file: String,
    /// Create the user file (0600) when it does not exist. Never overwrites.
    pub seed: bool,
    /// Log, for every event, which rule conditions matched or failed.
    pub debug: bool,
    pub max_backups: usize,
}

impl Default for FilterCfg {
    fn default() -> Self {
        Self {
            file: None,
            default_file: "$XDG_CONFIG_HOME/minisoc/alert_filter.yaml".into(),
            system_files: vec![],
            ai_file: "$XDG_CONFIG_HOME/minisoc/ai_filters.yaml".into(),
            seed: true,
            debug: false,
            max_backups: 20,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct RetentionCfg {
    pub days: i64,
    pub max_events: i64,
    pub export_recent: usize,
    pub export_discarded: usize,
    pub export_filtered: usize,
}

impl Default for RetentionCfg {
    fn default() -> Self {
        Self {
            days: 30,
            max_events: 20000,
            export_recent: 60,
            export_discarded: 60,
            export_filtered: 30,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct AiCfg {
    pub enable: bool,
    /// openai | anthropic | gemini | ollama | openai-compatible | custom
    pub provider: Option<String>,
    pub model: Option<String>,
    pub endpoint: Option<String>,
    /// Read at request time; never logged, never copied.
    pub api_key_file: Option<String>,
    /// Sending (redacted) events to a non-local endpoint must be opted in.
    pub allow_remote: bool,
    /// Reasoning effort for models that "think" (low | medium | high), passed
    /// to OpenRouter (`reasoning.effort`) and OpenAI (`reasoning_effort`).
    /// Their reasoning counts in the output budget. None: provider default.
    pub reasoning_effort: Option<String>,
    pub analysis: AnalysisCfg,
    pub limits: LimitsCfg,
    pub privacy: PrivacyCfg,
    pub auto_discard: AutoDiscardCfg,
    pub auto_filter: AutoFilterCfg,
    pub filter_review: FilterReviewCfg,
    /// name -> prompt file (system, analysis, enrichment, classification, filter, review)
    pub prompts: BTreeMap<String, String>,
    /// `<dir>/<name>.md` overrides everything, editable without rebuild.
    pub prompt_override_dir: String,
}

impl Default for AiCfg {
    fn default() -> Self {
        Self {
            enable: false,
            provider: None,
            model: None,
            endpoint: None,
            api_key_file: None,
            allow_remote: false,
            reasoning_effort: None,
            analysis: AnalysisCfg::default(),
            limits: LimitsCfg::default(),
            privacy: PrivacyCfg::default(),
            auto_discard: AutoDiscardCfg::default(),
            auto_filter: AutoFilterCfg::default(),
            filter_review: FilterReviewCfg::default(),
            prompts: BTreeMap::new(),
            prompt_override_dir: "$XDG_CONFIG_HOME/minisoc/prompts".into(),
        }
    }
}

