#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct AutoDiscardCfg {
    /// off | suggest | automatic
    pub mode: String,
    pub maximum_severity: String,
    pub minimum_confidence: f64,
    /// low | medium | high (the model's false_positive_likelihood)
    pub minimum_false_positive_likelihood: String,
    pub require_repeated_benign_pattern: bool,
    pub minimum_occurrences: i64,
}

impl Default for AutoDiscardCfg {
    fn default() -> Self {
        Self {
            mode: "off".into(),
            maximum_severity: "low".into(),
            minimum_confidence: 0.75,
            minimum_false_positive_likelihood: "high".into(),
            require_repeated_benign_pattern: true,
            minimum_occurrences: 2,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct AutoFilterCfg {
    /// off | suggest | automatic
    pub mode: String,
    pub minimum_confidence: f64,
    /// low | medium | high (the model's false_positive_likelihood)
    pub minimum_false_positive_likelihood: String,
    pub require_repeated_events: bool,
    pub minimum_occurrences: i64,
    /// critical and high are always protected, whatever this list says.
    pub protect_severity: Vec<String>,
    pub backup_before_write: bool,
}

impl Default for AutoFilterCfg {
    fn default() -> Self {
        Self {
            mode: "off".into(),
            minimum_confidence: 0.85,
            minimum_false_positive_likelihood: "high".into(),
            require_repeated_events: true,
            minimum_occurrences: 3,
            protect_severity: vec!["critical".into(), "high".into()],
            backup_before_write: true,
        }
    }
}

/// Scheduled AI review of the AI's own rules from the alerts the user closed
/// as false positive (and, as counter-examples, as true positive).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct FilterReviewCfg {
    /// off | suggest (pending proposals) | automatic (rules rewritten)
    pub mode: String,
    pub interval_hours: f64,
    /// Closures considered (days back).
    pub lookback_days: i64,
    /// Closed alerts sent per verdict (most recent first).
    pub max_alerts: usize,
    /// A rule must cover at least this many alerts closed as FP by the user.
    pub minimum_false_positives: usize,
    /// A rule younger than this (since its last change) is not modified nor
    /// deleted: its counter needs time.
    pub minimum_rule_age_hours: f64,
    /// A rule may be deleted when it excluded at most this many alerts since
    /// its last change (or when it would hide a TP).
    pub low_hits_threshold: i64,
    pub max_changes: usize,
    pub minimum_confidence: f64,
    pub backup_before_write: bool,
    /// Output budget of a review reply (a whole rule list), at least the
    /// analysis one.
    pub max_output_tokens: u32,
    /// Overrides `ai.reasoning_effort` for reviews (large inputs make
    /// reasoning models think long).
    pub reasoning_effort: Option<String>,
}

impl Default for FilterReviewCfg {
    fn default() -> Self {
        Self {
            mode: "off".into(),
            interval_hours: 24.0,
            lookback_days: 30,
            max_alerts: 200,
            minimum_false_positives: 3,
            minimum_rule_age_hours: 72.0,
            low_hits_threshold: 2,
            max_changes: 5,
            minimum_confidence: 0.7,
            backup_before_write: true,
            max_output_tokens: 16384,
            reasoning_effort: None,
        }
    }
}

pub fn expand(path: &str) -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/".into());
    let var = |k: &str, def: String| {
        std::env::var(k)
            .ok()
            .filter(|v| !v.is_empty())
            .unwrap_or(def)
    };
    // SAFETY: getuid has no preconditions.
    let uid = unsafe { libc_getuid() };
    let pairs = [
        (
            "XDG_CONFIG_HOME",
            var("XDG_CONFIG_HOME", format!("{home}/.config")),
        ),
        (
            "XDG_STATE_HOME",
            var("XDG_STATE_HOME", format!("{home}/.local/state")),
        ),
        (
            "XDG_RUNTIME_DIR",
            var("XDG_RUNTIME_DIR", format!("/run/user/{uid}")),
        ),
        ("HOME", home.clone()),
    ];
    let mut out = if let Some(rest) = path.strip_prefix("~/") {
        format!("{home}/{rest}")
    } else {
        path.to_string()
    };
    for (k, v) in pairs.iter() {
        out = out
            .replace(&format!("${{{k}}}"), v)
            .replace(&format!("${k}"), v);
    }
    PathBuf::from(out)
}

extern "C" {
    #[link_name = "getuid"]
    fn libc_getuid() -> u32;
}

impl Config {
    pub fn load(path: Option<&str>) -> Result<Self, String> {
        let env = std::env::var("MINISOC_CONFIG").ok();
        let path = path
            .map(str::to_string)
            .or(env)
            .unwrap_or_else(|| DEFAULT_CONFIG_PATH.into());
        match std::fs::read_to_string(&path) {
            Ok(s) if s.trim().is_empty() => Ok(Self::default()),
            Ok(s) => serde_json::from_str(&s).map_err(|e| format!("{path}: {e}")),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(Self::default()),
            Err(e) => Err(format!("{path}: {e}")),
        }
    }

    pub fn state_dir(&self) -> PathBuf {
        expand(&self.state_dir)
    }
    pub fn runtime_dir(&self) -> PathBuf {
        expand(&self.runtime_dir)
    }
    pub fn inbox_dir(&self) -> PathBuf {
        expand(&self.inbox_dir)
    }
    pub fn db_path(&self) -> PathBuf {
        self.state_dir().join("minisoc.sqlite3")
    }
    pub fn state_json(&self) -> PathBuf {
        self.runtime_dir().join("state.json")
    }
    pub fn backup_dir(&self) -> PathBuf {
        self.state_dir().join("filter-backups")
    }
    pub fn user_filter_file(&self) -> PathBuf {
        expand(
            self.filter
                .file
                .as_deref()
                .unwrap_or(&self.filter.default_file),
        )
    }
    pub fn ai_filter_file(&self) -> PathBuf {
        expand(&self.filter.ai_file)
    }
    pub fn ai_backup_dir(&self) -> PathBuf {
        self.backup_dir().join("ai")
    }
    pub fn system_filter_files(&self) -> Vec<PathBuf> {
        self.filter.system_files.iter().map(|p| expand(p)).collect()
    }
    pub fn all_spool_dirs(&self) -> Vec<PathBuf> {
        let mut v: Vec<PathBuf> = self.spool_dirs.iter().map(|p| expand(p)).collect();
        v.push(self.inbox_dir());
        v
    }
}
